const body = $input.first().json.body || {};
const alerts = Array.isArray(body.alerts) ? body.alerts : [];
if (alerts.length === 0) {
  throw new Error('Keine Alerts im Alertmanager-Payload');
}
const ICON = { critical: '\u{1F6A8}', warning: '\u26A0\uFE0F' };
const entschaerfen = (text) => String(text || '').replace(/@(channel|all|here)\b/gi, '@\u200b$1');
const zeile = (alert) => {
  const labels = alert.labels || {};
  const notes = alert.annotations || {};
  const ort = [labels.namespace, labels.pod || labels.instance || labels.job].filter(Boolean).join('/');
  const text = notes.summary || notes.description || notes.message || '';
  const icon = alert.status === 'resolved' ? '\u2705' : (ICON[labels.severity] || '\u2753');
  return '- ' + icon + ' **' + (labels.alertname || 'Alert') + '**' + (ort ? ' (' + ort + ')' : '') + (text ? ' \u2013 ' + text : '');
};
const feuernd = alerts.filter((alert) => alert.status !== 'resolved');
const behoben = alerts.filter((alert) => alert.status === 'resolved');
const abschnitt = (titel, liste) => [titel, ...liste.slice(0, 15).map(zeile)].concat(liste.length > 15 ? ['- ... und ' + (liste.length - 15) + ' weitere'] : []).join('\n');
const teile = [];
if (feuernd.length > 0) teile.push(abschnitt('#### \u{1F525} ' + feuernd.length + ' Alert(s) aktiv', feuernd));
if (behoben.length > 0) teile.push(abschnitt('#### \u2705 ' + behoben.length + ' Alert(s) behoben', behoben));
const message = entschaerfen(teile.join('\n\n'));
const ausgabe = { channel: 'alerts', message };
if (feuernd.length > 0) {
  const namen = [...new Set(feuernd.map((alert) => (alert.labels || {}).alertname || 'Alert'))];
  const nonce = require('crypto').randomBytes(16).toString('hex');
  ausgabe.props = {
    aktion_nonce: nonce,
    aktion_titel: ('Alert: ' + namen.join(', ')).slice(0, 150),
    aktion_text: entschaerfen(feuernd.map((alert) => zeile(alert)).join('\n')),
    attachments: [
      {
        fallback: 'Aktionen',
        actions: [
          {
            id: 'ticket',
            name: 'Ticket anlegen',
            type: 'button',
            style: 'primary',
            integration: { url: 'http://n8n.n8n.svc.cluster.local/webhook/mattermost-aktion', context: { aktion: 'ticket', nonce } },
          },
        ],
      },
    ],
  };
}
return [{ json: ausgabe }];

const quellen = $('Nachricht bauen').all().map((item) => item.json);
const kanaele = $input.all().map((item) => item.json).filter((kanal) => kanal && kanal.name);
return quellen.map((quelle) => {
  const ziel = kanaele.find((kanal) => kanal.name === quelle.channel);
  if (!ziel) {
    throw new Error('Kanal "' + quelle.channel + '" nicht gefunden oder n8n-bot ist dort kein Mitglied. Bekannt: ' + kanaele.map((kanal) => kanal.name).join(', '));
  }
  return { json: { ...quelle, channel_id: ziel.id } };
});
